    ('admin.mail.marketing.hint.bounce.lead', 'zh-CN', '失败的投递按错误分类处理：临时故障交给队列退避重试；', 200, 'admin', 'admin/mail_marketing.html', 1, now(), now()),
    ('admin.mail.marketing.hint.bounce.lead', 'en-US', 'Failed deliveries are handled by error class: temporary faults go back to the queue with backoff; ', 200, 'admin', 'admin/mail_marketing.html', 1, now(), now()),
    ('admin.mail.marketing.hint.bounce.strong', 'zh-CN', '硬退信', 200, 'admin', 'admin/mail_marketing.html', 1, now(), now()),
